export const workstreamBaseUrlFromMcpEndpoint = (mcpEndpoint: string): string =>
  mcpEndpoint.endsWith("/mcp")
    ? mcpEndpoint.slice(0, -"/mcp".length)
    : mcpEndpoint.replace(/\/$/, "");

